<template><section aria-label="科研任务技术目录"><p>目录只提供任务技术状态；不授予临床分件、外部模型处理或导出权限。</p><p v-if="!authorized" role="status">当前会话不能读取科研任务目录。</p><template v-else><el-button :disabled="busy" @click="load(1)">刷新科研任务技术目录</el-button><el-table :data="rows" aria-label="科研待核问题任务列表"><el-table-column prop="run_id" label="任务标识" /><el-table-column prop="status" label="记录状态" /><el-table-column prop="create_time" label="提交UTC" /><el-table-column label="操作"><template #default="{row}"><el-button :disabled="busy" @click="emit('open',row.run_id)">按当前权限核对本任务</el-button></template></el-table-column></el-table><el-button :disabled="busy||page<=1" @click="load(page-1)">上一页科研任务</el-button><span>第{{ page }}页，共{{ total }}件</span><el-button :disabled="busy||page*20>=total" @click="load(page+1)">下一页科研任务</el-button></template><p v-if="error" role="alert">{{ error }}</p></section></template>
<script setup>
import {computed,onActivated,onBeforeUnmount,onDeactivated,onMounted,ref,watch} from 'vue';
import {useStore} from 'vuex';
import {supportCanonical as canonical,supportId as uuid} from '@/api/inpatientSupport';
import {getResearchTasks,researchTaskDirectoryValid} from '@/api/ai/researchCohortTasks';
const props=defineProps({active:{type:Boolean,default:true},auditOnly:{type:Boolean,default:false},caseId:{type:String,default:null}}),emit=defineEmits(['open','invalidate']),store=useStore(),rows=ref([]),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),kept=ref(true);
const identity=computed(()=>canonical([store.state.user?.accessToken??null,store.state.user?.username??null,store.state.user?.permissions??null,props.auditOnly,props.caseId])),authorized=computed(()=>{const roles=store.state.user?.permissions;return props.active&&kept.value&&!!store.state.user?.accessToken&&Array.isArray(roles)&&roles.length>0&&new Set(roles).size===roles.length&&roles.every(v=>['super_admin','admin','director'].includes(v))&&(!props.auditOnly||roles.includes('super_admin'))&&(props.caseId===null||uuid(props.caseId));});
let epoch=0,mounted=false;function clear(){epoch++;rows.value=[];total.value=0;busy.value=false;error.value='';emit('invalidate');}
async function load(selected=1){if(!authorized.value)return;clear();const stamp=++epoch,subject=identity.value,current=()=>mounted&&authorized.value&&stamp===epoch&&subject===identity.value;busy.value=true;try{const data=(await getResearchTasks({page:selected,size:20,audit_only:props.auditOnly,...(props.caseId?{case_id:props.caseId}:{})})).data;if(!current())return;if(!researchTaskDirectoryValid(data,{page:selected,size:20,caseId:props.caseId}))throw new Error('任务技术目录闭集无效');rows.value=data.items;total.value=data.total;page.value=selected;}catch(cause){if(current()){clear();error.value=[401,403].includes(cause?.response?.status)?'当前科研任务目录权限不足。':'科研技术目录无法核对，未保留旧行。';}}finally{if(current())busy.value=false;}}
watch([identity,()=>props.active,kept],()=>{clear();if(mounted&&authorized.value)load(1);},{flush:'sync'});onMounted(()=>{mounted=true;if(authorized.value)load(1);});onActivated(()=>{kept.value=true;});onDeactivated(()=>{kept.value=false;});onBeforeUnmount(()=>{mounted=false;clear();});
</script>
